  'help.type.cant_login': 'Nie mogę się zalogować',
  'help.type.email_issue': 'Problem z e-mailem',
  'help.type.security': 'Bezpieczeństwo',
  'help.type.other': 'Inne',
  'help.faq.cantLogin.q': 'Nie mogę zalogować się na moje konto',
  'help.faq.cantLogin.a': 'Upewnij się, że używasz poprawnego e-maila i hasła. Jeśli zapomniałeś hasła, kliknij "Zapomniałeś hasła?" na ekranie logowania. Jeśli problem nadal występuje, utwórz zgłoszenie wsparcia.',
  'help.faq.notReceiving.q': 'Nie otrzymuję e-maili',
  'help.faq.notReceiving.a': 'Najpierw sprawdź folder Spam. Upewnij się, że masz wystarczająco dużo miejsca. Jeśli problem nadal występuje, sprawdź, czy nadawca ma poprawny adres e-mail i stwórz zgłoszenie do wsparcia.',
  'help.faq.cantSend.q': 'Nie mogę wysłać e-maili',
  'help.faq.cantSend.a': 'Sprawdź swoje połączenie internetowe i upewnij się, że adres e-mail odbiorcy jest poprawny. Sprawdź, czy masz załączniki, które są za duże (max 25MB). Spróbuj ponownie za kilka minut.',
  'help.faq.forgotPassword.q': 'Zapomniałem hasła',
  'help.faq.forgotPassword.a': 'Na ekranie logowania kliknij "Zapomniałeś hasła?" i postępuj zgodnie z instrukcjami, aby zresetować hasło przez swój adres e-mail do odzyskiwania.',
  'help.faq.accountSecurity.q': 'Myślę, że moje konto zostało przejęte',
  'help.faq.accountSecurity.a': 'Natychmiast zmień swoje hasło. Sprawdź folder Wysłane, czy nie ma tam wiadomości, których nie wysłałeś. Włącz uwierzytelnianie dwuskładnikowe w Ustawienia > Bezpieczeństwo. W razie potrzeby stwórz pilne zgłoszenie do wsparcia.',
  'help.faq.appAccess.q': 'Jak uzyskać dostęp do aplikacji na telefonie?',
  'help.faq.appAccess.a': 'Możesz uzyskać dostęp do Chatyy przez dowolną przeglądarkę mobilną na chatyy.com.br lub pobrać naszą aplikację z sklepu z aplikacjami na swoim urządzeniu.',

  // Privacy modal
  'privacy.title': 'Polityka Prywatności',
  'privacy.subtitle': 'Jak chronimy i przetwarzamy Twoje dane',
  'privacy.lastUpdated': 'Ostatnia aktualizacja: marzec 2026',
  'privacy.dataCollection.title': 'Zbieranie Danych',
  'privacy.dataCollection.body': 'Zbieramy tylko informacje niezbędne do świadczenia naszej usługi e-mail: Twoje imię, adres e-mail i treść wiadomości, które wysyłasz i otrzymujesz. Nie sprzedajemy ani nie udostępniamy Twoich danych osobowych osobom trzecim w celach marketingowych.',
  'privacy.dataUsage.title': 'Jak Używamy Twoich Danych',
  'privacy.dataUsage.body': 'Twoje dane są używane wyłącznie do działania i ulepszania usługi e-mail, w tym dostarczania wiadomości, filtrowania spamu, oferowania funkcji opartych na AI (za Twoją zgodą) oraz utrzymywania bezpieczeństwa konta.',
  'privacy.dataSecurity.title': 'Bezpieczeństwo Danych',
  'privacy.dataSecurity.body': 'Używamy standardowego szyfrowania (TLS/SSL) dla wszystkich danych w tranzycie i w spoczynku. Sesje są chronione za pomocą szyfrowanych tokenów i ochrony CSRF. Regularnie audytujemy nasze praktyki bezpieczeństwa.',
  'privacy.cookies.title': 'Ciasteczka i Pamięć Lokalna',
  'privacy.cookies.body': 'Używamy niezbędnych ciasteczek i pamięci lokalnej, aby utrzymać Twoją sesję, zapamiętać Twoje preferencje (motyw, język) i zapewnić płynne doświadczenie. Nie używamy ciasteczek śledzących od osób trzecich.',
  'privacy.thirdParties.title': 'Usługi Osób Trzecich',
  'privacy.thirdParties.body': 'Możemy korzystać z usług osób trzecich w celu zapewnienia określonej funkcjonalności, takiej jak funkcje AI (Anthropic Claude) i powiadomienia push. Usługi te są związane własnymi politykami prywatności i przetwarzają tylko minimalne dane wymagane.',
  'privacy.rights.title': 'Twoje Prawa',
  'privacy.rights.body': 'Masz prawo do dostępu, poprawiania, eksportowania lub usuwania swoich danych osobowych w dowolnym momencie. Możesz zarządzać swoimi danymi przez Ustawienia lub kontaktując się z naszym zespołem wsparcia.',
  'privacy.contact.title': 'Skontaktuj się z Nami',
  'privacy.contact.body': 'W przypadku pytań dotyczących prywatności lub żądań danych skontaktuj się z nami pod adresem privacy@chatyy.com.br. Odpowiemy w ciągu 30 dni.',

  // Terms modal
  'terms.title': 'Warunki Usługi',
  'terms.subtitle': 'Zasady korzystania z Chatyy',
  'terms.lastUpdated': 'Ostatnia aktualizacja: marzec 2026',
  'terms.acceptance.title': 'Akceptacja Warunków',
  'terms.acceptance.body': 'Korzystając z Chatyy, zgadzasz się na przestrzeganie tych Warunków Usługi. Jeśli nie zgadzasz się z jakąkolwiek częścią tych warunków, nie możesz korzystać z usługi.',
  'terms.services.title': 'Opis Usług',
  'terms.services.body': 'Chatyy oferuje usługi komunikacji e-mailowej, w tym wysyłanie, odbieranie i zarządzanie e-mailami, a także funkcje oparte na AI, integrację kalendarza i możliwości wideokonferencji.',
  'terms.accounts.title': 'Konta Użytkowników',
  'terms.accounts.body': 'Jesteś odpowiedzialny za utrzymanie bezpieczeństwa swoich danych logowania. Nie możesz dzielić się swoim hasłem ani pozwalać na nieautoryzowany dostęp do swojego konta. Musisz mieć co najmniej 13 lat, aby korzystać z tej usługi.',
  'terms.conduct.title': 'Akceptowalne Użytkowanie',
  'terms.conduct.body': 'Zgadzasz się nie używać usługi do wysyłania spamu, złośliwego oprogramowania, phishingu ani żadnych nielegalnych treści. Nie możesz próbować uzyskać dostępu do kont innych użytkowników ani zakłócać infrastruktury usługi.',
  'terms.content.title': 'Własność Treści',
  'terms.content.body': 'Zachowujesz prawo własności do wszystkich treści, które tworzysz i wysyłasz za pośrednictwem usługi. Nie rościmy sobie praw do Twoich e-maili ani załączników. Możemy przetwarzać treści w miarę potrzeby, aby świadczyć usługę.',
  'terms.limitation.title': 'Ograniczenie Odpowiedzialności',
  'terms.limitation.body': 'Chatyy jest dostarczane "tak jak jest". Dążymy do 99,9% dostępności, ale nie gwarantujemy nieprzerwanej usługi. Nie ponosimy odpowiedzialności za jakiekolwiek pośrednie, przypadkowe lub wynikowe szkody wynikające z korzystania z usługi.',
