  'plans.faqHowFamilyAnswer': 'Możesz dodać do 4 członków rodziny. Wszyscy dzielą 500GB pamięci i korzystają ze wszystkich korzyści Chatyy One. Każda osoba ma swoją prywatną przestrzeń — nikt nie może zobaczyć plików innych.',
  'plans.faqChangePlanAnswer': 'Tak! Jeśli ulepszysz z Chatyy Plus do Pro, zapłacisz tylko różnicę proporcjonalną. Jeśli obniżysz, obecny plan będzie trwał do końca okresu.',
  'plans.faqCardDeclined': 'Moja karta została odrzucona, co robić?',
  'plans.faqCardDeclinedAnswer': 'Masz 7 dni na zaktualizowanie swojej karty. W tym okresie wszystkie twoje korzyści będą działać. Po 7 dniach plan wraca do darmowego.',
  'plans.faqDataSafe': 'Czy moje dane są bezpieczne?',
  'plans.faqDataSafeAnswer': 'Tak! Twoje dane płatnicze są przetwarzane z szyfrowaniem end-to-end. Nie przechowujemy numeru twojej karty — tylko ostatnie 4 cyfry dla twojej informacji.',
